/* eslint-disable @typescript-eslint/no-explicit-any */
import {
	ComponentType,
	Fragment,
	JSXElementConstructor,
	ReactElement,
	ReactNode,
	ReactPortal,
	cloneElement,
	createElement,
	isValidElement,
} from 'react'

import type { Renderable } from './Renderable'
import { isGatewayElement } from './useGateway'
import { isFunction, isPlainObject } from './utils'

/**
 * Used alongside renderable type to enable partial and conditional rendering of
 * some JSX in a simpler and more conventional manner.
 *
 * @param bespoke - Specific part to be rendered
 * @param default - The JSX part that will be rendered if "true" is passed
 * @param context - Additional context passed to custom render function
 * @param wrapper - Wrapper that might be used to be used with both bespokePart and defaultPart
 * @param options - Additional hints on how to render the slot
 *
 * @example
 * Having component:
 * function Component({ renderText }: { renderText: Renderable }) {
 *     return (
 *     	 <div>
 *     	    {renderSlot(renderText, () => <Text>Default text</Text>, (part) => <Text>{part}</Text>)}
 *       </div>
 *     )
 * } or:
 *
 * renderSlot(renderText, () => <Text>Default text</Text>)
 * renderSlot(renderText, () => <Text>Default text</Text>, (part) => <Text>{part}</Text>)
 *
 * <Component renderText />
 *  => <Text>Default text</Text>
 *
 * <Component renderText={false} />
 *  => null
 *
 * renderSlot(true, () => <Text>Default text</Text>, (part) => <li>{part}</li>)
 *  => <li><Text>Default text</Text></li>
 *
 * renderSlot(<strong>Some text</strong>, () => <Text>Default text</Text>, (part) => <li>{part}</li>)
 *  => <li><strong>Some text</strong></li>
 *
 * renderSlot(() => <strong>Some text</strong>, () => <Text>Default text</Text>, (part) => <li>{part}</li>)
 *  => <li><strong>Some text</strong></li>
 *
 *  renderSlot((DefaultPart) => <strong><DefaultPart /></strong>, () => <Text>Default text</Text>, (part) => <li>{part}</li>)
 *  => <strong><Text>Default text</Text></strong>
 */

// Accept functional component, class component, or element instance
export type DefaultLike<P extends object> =
	| ComponentType<P>
	| JSXElementConstructor<P>
	| ReactElement<P>
	| null
	| undefined

type PropsOfDefault<T> =
	T extends ComponentType<infer P>
		? P
		: T extends ReactElement<infer P>
			? P
			: T extends JSXElementConstructor<infer P>
				? P
				: Record<string, never>

type RenderSlotOptions = {
	wrapNonElementWithDefault?: boolean
	passContextToDefault?: boolean
}

type AllProps<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
> = {
	bespoke: Renderable<P, C>
	default?: D
	context?: C
	wrapper?: (part: ReactNode, index?: number) => ReactNode
	options?: RenderSlotOptions
}

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(bespoke: Renderable<P, C>): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(bespoke: Renderable<P, C>, defNode: D): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(bespoke: Renderable<P, C>, defNode: D, context: C): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: D,
	context: C | undefined,
	options: RenderSlotOptions
): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: D,
	context: C,
	wrapper: (part: ReactNode, index?: number) => ReactNode
): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: D,
	context: C,
	wrapper: (part: ReactNode, index?: number) => ReactNode,
	options: RenderSlotOptions
): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(args: AllProps<D, P, C>): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(bespoke: Renderable<P, C>, args: Omit<AllProps<D, P, C>, 'bespoke'>): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: ReactNode | ComponentType<P>,
	args: Omit<AllProps<D, P, C>, 'bespoke' | 'default'>
): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: ReactNode | ComponentType<P>,
	context: C,
	args: Omit<AllProps<D, P, C>, 'bespoke' | 'default' | 'context'>
): ReactNode

export function renderSlot<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>(
	bespoke: Renderable<P, C>,
	defNode: ReactNode | ComponentType<P>,
	context: C,
	wrapper: (part: ReactNode, index?: number) => ReactNode,
	args: Omit<AllProps<D, P, C>, 'bespoke' | 'default' | 'context' | 'wrapper'>
): ReactNode

export function renderSlot(...args: any[]): ReactNode {
	switch (args.length) {
		case 1:
			return renderSlotWithObject(
				isPlainObject(args[0]) && 'bespoke' in args[0] ? args[0] : { bespoke: args[0] }
			)
		case 2:
			return renderSlotWithObject({
				bespoke: args[0],
				...(isSlotConfig(args[1], ['default', 'context', 'wrapper', 'options'])
					? args[1]
					: { default: args[1] }),
			})
		case 3:
			return renderSlotWithObject({
				bespoke: args[0],
				default: args[1],
				...(isSlotConfig(args[2], ['context', 'wrapper', 'options'])
					? args[2]
					: { context: args[2] }),
			})
		case 4:
			return renderSlotWithObject({
				bespoke: args[0],
				default: args[1],
				context: args[2],
				...(isFunction(args[3])
					? { wrapper: args[3] }
					: isRenderSlotOptions(args[3])
						? { options: args[3] }
						: args[3]),
			})
		case 5:
			return renderSlotWithObject({
				bespoke: args[0],
				default: args[1],
				context: args[2],
				wrapper: args[3],
				options: args[4],
			})
		default:
			return null
	}
}

const REACT_PORTAL_TYPE = Symbol.for('react.portal')
const isPortal = (x: unknown): x is ReactPortal => !!x && (x as any).$$typeof === REACT_PORTAL_TYPE

function renderSlotWithObject<
	D extends DefaultLike<any>,
	P extends object = PropsOfDefault<D>,
	C extends object = Record<string, unknown>,
>({
	bespoke: bespokePart,
	default: defaultPart,
	context: contextPart,
	wrapper: wrapperPart,
	options: optionsPart,
}: AllProps<D, P, C>): ReactNode {
	const { wrapNonElementWithDefault, passContextToDefault } = optionsPart ?? {}

	// Don't render part at all in those three cases.
	if (bespokePart === undefined || bespokePart === false || bespokePart === null) {
		return null
	}

	const renderContent = (slot: Renderable<P, C>): ReactNode => {
		// Render default implementation.
		if (slot === true) {
			return isFunction(defaultPart)
				? createElement(defaultPart, {} as P)
				: ((defaultPart ?? null) as ReactNode)
		}

		// If a function is passed, render it with the default part.
		if (isFunction(slot)) {
			return slot(
				isFunction(defaultPart)
					? defaultPart
					: isValidElement(defaultPart)
						? (props) => cloneElement(defaultPart, props as P)
						: () => null,
				contextPart ?? ({} as C)
			)
		}

		// Handle additional options.
		if (wrapNonElementWithDefault && !isObject(slot)) {
			const props = {
				children: slot,
				...(passContextToDefault ? (contextPart ?? {}) : {}),
			} as unknown as P

			return isFunction(defaultPart)
				? createElement(defaultPart, props)
				: isValidElement(defaultPart)
					? cloneElement(defaultPart, props)
					: null
		}

		// If an object configuration was passed (defaultPart props).
		if (isObject(slot) && !isValidElement(slot)) {
			return isFunction(defaultPart)
				? createElement(defaultPart, slot)
				: isValidElement(defaultPart)
					? cloneElement(defaultPart, slot)
					: null
		}

		// In the case of any different React node, just return the value.
		return slot as ReactNode
	}

	const renderItem = (slot: Renderable<P, C>, index: number): ReactNode => {
		const content = renderContent(slot)

		// Mount gateway capture components without applying the slot wrapper.
		if (isGatewayElement(content)) {
			return content
		}

		// Don't wrap portals.
		if (isPortal(content)) {
			return content
		}

		// Wrap everything if needed.
		return wrapperPart ? wrapperPart(content, index) : content
	}

	if (Array.isArray(bespokePart)) {
		return createElement(Fragment, {
			children: bespokePart
				.filter((item) => item !== false && item !== null && item !== undefined)
				.map((item, index) => {
					const rendered = renderItem(item, index)
					return isValidElement(rendered)
						? cloneElement(rendered, { key: rendered.key ?? index })
						: createElement(Fragment, { children: rendered, key: index })
				}),
		})
	} else {
		return renderItem(bespokePart, 0)
	}
}

function isObject(obj: any): obj is object {
	return isPlainObject(obj)
}

function isSlotConfig(value: unknown, allowedKeys: string[]): boolean {
	if (!isPlainObject(value) || isValidElement(value)) {
		return false
	}

	const config = value as Record<string, unknown>
	const keys = Object.keys(config)

	if (!keys.every((key) => allowedKeys.includes(key))) {
		return false
	}

	if ('wrapper' in config && config.wrapper !== undefined && !isFunction(config.wrapper)) {
		return false
	}

	if (
		'options' in config &&
		config.options !== undefined &&
		!isRenderSlotOptions(config.options)
	) {
		return false
	}

	return true
}

function isRenderSlotOptions(value: unknown): value is RenderSlotOptions {
	if (!isPlainObject(value)) {
		return false
	}

	const options = value as Record<string, unknown>
	return (
		Object.keys(options).every(
			(key) => key === 'wrapNonElementWithDefault' || key === 'passContextToDefault'
		) &&
		(options.wrapNonElementWithDefault === undefined ||
			typeof options.wrapNonElementWithDefault === 'boolean') &&
		(options.passContextToDefault === undefined ||
			typeof options.passContextToDefault === 'boolean')
	)
}